from lib import *
import json, numpy as np
N = J("nums.json"); IM = J("impact.json"); ST = J("staged.json"); par = J("parity2.json")
NM = {"ULVR": "Unilever", "NESN": "Nestlé", "WIL": "Wilmar"}

def build(doc):
    h1(doc, "Chapter 6  Strategic Recommendations and Managerial Decision Rules")
    para(doc, "This chapter turns the evidence into decisions for the two brand owners and for Wilmar (Table 6.1 summarises the options). Where a rule rests on the cost-benefit model or on the SPOEI, we say so; where a threshold is a starting value to be calibrated, we say that too. No rule below rests on a trained classifier, because none has been estimated (Chapter 4).", 10.5, 6)
    h2(doc, "6.1  Procurement intervention strategies")
    table_cap(doc, 6, "Interventions assessed and verdicts")
    table(doc, ["Intervention", "What the evidence says", "Verdict"], [
        ["Stay with mass balance and certification only", "Cannot supply plot-level evidence (Table 1.1); highest untraced cost (Figure 5.2; Table 5.5 for the other scenarios)", "**Reject** for EU-bound in-scope volume from 30-Dec-2026"],
        ["Staged traceability: central database first, ledger-ready, escalate on triggers", "Database pays in 79–93% of simulated worlds and has the thinner lower tail; ledger wins only under adverse/severe enforcement or with lower cost (Chapter 5)", "**Adopt** (Unilever, Wilmar); Nestlé may go straight to the ledger"],
        ["Permissioned consortium blockchain from day one", "Higher assurance and the largest benefit in severe cases, but longer ramp-up, higher cost, and a lower tail of −USD 17 m to −70 m", "**Conditional** on triggers R1–R2 below"],
        ["Vertical integration (own plantations or mills)", "Palm is about 3.0% of Unilever’s and 1.5% of Nestlé’s COGS (ASSUMPTION), against a USD 8–14 m traceability programme. The risk is informational, not capacity; the assets are not specific to the buyer (TCE logic, Chapter 2), and ownership moves deforestation liability onto the buyer’s own balance sheet", "**Do not pursue.** Use contractual integration: offtake, premium and co-funding of mill-level traceability"],
        ["Drop Wilmar if its ESG score falls below a threshold", "Wilmar’s BESG score (6.15) is the *highest* of the three and rose 2.3× while Scope 1 emissions rose 2.6×: the score measures disclosure. A score threshold would never fire, while the real risks (interest cover 2.1×, legal and governance headlines, conduct flags) go unmanaged", "**Do not use an ESG-score trigger.** Use verified-coverage covenants (R5) and financial/legal triggers (R4)"],
        ["Diversify the refiner base (dual sourcing)", "SPLC shows no visible palm refiner for either brand owner; Nestlé’s news already names Musim Mas and AAK as partners; substitution cost is small relative to the benefit (Figure 5.7: USD 5–27 m for Unilever at today’s 30% coverage)", "**Adopt:** cap any single refiner at a share set in the pilot (starting value 40%)"],
        ["Hedging and inventory", "Palm price volatility is about 17% a year; for the brand owners palm is a small cost share, so hedging changes margin little. For Wilmar, with a 3.2% operating margin, price and spread management matters far more", "**Wilmar:** formal hedge policy; **brand owners:** limited, via buffer stock of compliant oil"],
    ], [3.9, 8.5, 4.0], 8, ["l", "l", "l"], bold_first_col=True)
    h3(doc, "The value of staging")
    para(doc, "A staged programme pays the database cost now and the ledger cost only if enforcement becomes severe. Its value lies between two bounds: a **conservative** one in which the switch repeats the full ledger cost on top of the sunk database cost, and an **upper** one in which the firm knows the regime in advance. Table 6.2 reports both, from the same mixed-regime simulation.")
    rows = []
    for k in ("ULVR", "NESN", "WIL"):
        g = lambda n: ST[f"{k}|{n}"]
        rows.append([NM[k], f"{g('DB')['mean']:.0f} / {g('DB')['p5']:.0f}", f"{g('BC')['mean']:.0f} / {g('BC')['p5']:.0f}", f"{g('Staged (conservative)')['mean']:.0f} / {g('Staged (conservative)')['p5']:.0f}", f"{g('Staged (upper)')['mean']:.0f} / {g('Staged (upper)')['p5']:.0f}"])
    table_cap(doc, 6, "Mean / 5th-percentile NPV benefit by strategy, mixed regimes (USD m)")
    table(doc, ["Firm", "Central database only", "Blockchain now", "Staged (conservative)", "Staged (upper bound)"], rows, [2.6, 3.4, 3.4, 3.5, 3.5], 8.5, ["l", "c", "c", "c", "c"])
    note(doc, "Source: authors’ calculations; seed 42. Switch to the ledger only in worlds drawn as severe-enforcement (25% of draws). Conservative bound subtracts the deterministic PV of the database programme when the switch occurs.")
    para(doc, "Two lessons follow. Staging **keeps the database’s thin lower tail** (5th percentile −USD 13 m, −2 m and −23 m, against −33 m, −17 m and −70 m for the ledger now) while keeping the ledger option. But it adds expected value over the database only if the migration is cheap: with full double payment the staged path is worse than the database alone for Unilever and Wilmar. The practical requirement is therefore a *ledger-ready* database, built on standard identifiers (lot IDs, plot hashes) so that migration reuses most of the earlier spend. That is a design rule for the first procurement, not an afterthought.")
    h3(doc, "What each firm should do")
    bullets(doc, [
        "**Unilever.** Fund the central stack (CapEx about USD 8 m, OpEx 3 m a year, ASSUMPTION), require geolocated mill lists from every palm supplier by end-2026, and put refiners on the SPOEI tiering rule (R3). Treat the ledger as a trigger-based option (R1).",
        "**Nestlé.** Nestlé is the one firm whose base case already favours the ledger (+USD 2.3 m; parity at assurance 0.88). Run a consortium pilot with the refiners it already works with (Musim Mas, AAK and others) and use Wilmar’s data as an input rather than a dependency. Nestlé also holds the most inventory (96 days) and its lowest operating margin of FY2019–25, so cost discipline on the programme matters.",
        "**Wilmar.** Wilmar has the largest absolute benefit and the highest exposure: its untraced expected loss is about 15% of one year’s operating income in the base case (Section 6.2). It should build the central stack for its own supply (CapEx about USD 25 m), use its leverage over plantation suppliers (27% cost-weighted share of their revenue) to require geolocation, and publish mill-level lists. These steps also pre-empt the covenants its customers will impose.",
    ], 10, False, 3)

    h2(doc, "6.2  Risk–cost trade-off heat map")
    para(doc, "Figure 6.1 places the three firms on a probability-versus-impact map. The horizontal axis is the SPOEI (the probability proxy); the vertical axis is the PV of seven-year expected untraced loss as a share of FY2025 operating income, from the Chapter 5 model (a base-case dot and a severe-case triangle for each firm). Bubble size is the blockchain’s base-case NPV benefit.")
    figure(doc, 6, "f18_heatmap.png", "Risk–cost heat map: SPOEI versus economic impact of untraced exposure", "Source: Bloomberg-based SPOEI (Chapter 4); impact from companion model (ASSUMPTION inputs); FY2025 operating income converted at EUR 1.15 and CHF 1.25 per USD.", width=15.8)
    para(doc, f"The map separates the three firms clearly. **Wilmar** sits in the top-right: its SPOEI is 64 and its untraced loss is **{IM['imp']['WIL']:.1f}% of one year’s operating income in the base case and {IM['imp_sev']['WIL']:.0f}% in the severe case**. For **Unilever** and **Nestlé** the P&L impact is below 1% in the base case and under 3% in the severe case; their exposure is reputational and regulatory rather than financial. That is why their decision rule is to buy optionality cheaply, whereas Wilmar’s is to build capacity now.")
    para(doc, "At supplier level, Figure 3.2 is the working map for Wilmar’s visible plantation nodes. Suppliers in the high-leverage zone (Andira Agro, Gozco, AEP Pinago and Bakrie Sumatera, where Wilmar supplies 22–99% of revenue) can be *required* to supply geolocation and accept audits at little cost to Wilmar; suppliers with low leverage (for example, Dharma Satya with 13%) need co-investment or a longer ramp. Related parties (Wilmar Cahaya, Yihai Kerry Arawana) should be brought into the group’s own system first.")
    h2(doc, "6.3  Managerial decision rules")
    para(doc, "Each rule in Table 6.3 has a trigger that can be read from Bloomberg or from the traceability system, an action, and a status. **Anchored** means the threshold is tied to a number in this report; **starting value** means it is a reasoned default to be calibrated on the 10-year panel; no rule is derived from a classifier.", after=4)
    table_cap(doc, 6, "If–then decision rules")
    table(doc, ["#", "IF (trigger)", "THEN (action)", "Basis and status"], [
        ["R1", "A member-state authority publishes the first EUDR penalty or seizure against a palm-oil operator, OR the Commission confirms a non-compliance finding for a peer", "Treat enforcement as **adverse**: approve the migration of the central database to the permissioned ledger and open the consortium charter", "Adverse case: ledger leads the database by USD 3.5–15 m (Table 5.5); regulatory-event parity at 1.8–2.1× base. **Anchored**"],
        ["R2", f"Adverse-news severity for a Tier-1 supplier rises more than 2σ above its trailing 12-month mean (CN) AND the front-month palm contract (KO1) rises 15% or more in 90 days", "Start a Tier-2 audit within 30 days: re-run the satellite check on that supplier’s mills and hold escrow on new lots until it clears", "Severe case combines higher controversy (×2.5) and palm price (+30%); 15% is half the severe shock. Sentiment σ needs the CN series. **Starting value**"],
        ["R3", "Supplier SPOEI ≥ 60 (Wilmar 63.5); 50–59 (Unilever 53.0); < 50 (Nestlé 39.9)", "≥ 60: Tier-2 audit and quarterly review. 50–59: watch list, semi-annual. < 50: annual review", "Cut-offs follow the observed spread and the ranking was stable (Chapter 4). **Starting value**, recalibrate on the panel"],
        ["R4", "A counterparty’s interest cover falls below 3.0× or drops by more than 30% in a year", "Qualify a second source for its volume, move payments to escrow, and ask for a financing and sanctions disclosure", "Interest cover adds 6–7 points to Wilmar’s SPOEI premium (the largest single driver against Unilever); Wilmar is at 2.1×. **Anchored**"],
        ["R5", "Verified plot-level coverage of a supplier’s volume to us is below 60% at end-2026, 80% at end-2027 or 90% at end-2029", "Cap its share of incremental volume and shift the balance to suppliers above the threshold. Escalate to exit only after two missed milestones", "Steady-state coverage assumed: 80% (database) and 90% (ledger). Substitution is cheap at these levels (Figure 5.7). **Anchored**"],
        ["R6", "A supplier’s BESG score rises while its reported Scope 1 or Scope 3 emissions rise 10% or more over two years", "Flag *disclosure–footprint divergence*; require independently verified emissions data before the score is used in any sourcing decision", "Wilmar: BESG 2.71 → 6.15 while Scope 1 rose 2.6× (Figure 3.5). **Anchored**"],
        ["R7", "30-day palm price volatility exceeds 25% (about 1.5× the 17% sample level)", "Extend forward cover for compliant-origin volume and raise the safety stock from the current level to the next tier; for Wilmar, tighten hedge limits", "Volatility sample is 8 weeks; threshold must be set on the 10-year KO1 distribution. **Starting value**"],
    ], [0.9, 5.1, 5.4, 5.0], 7.8, ["c", "l", "l", "l"], bold_first_col=True)
    note(doc, "Rules R1–R7 are decision aids, not model outputs. Each should be backtested on the Terminal history before adoption.")
    callout(doc, "Implementation note", "Rules R1, R2 and R5 should be written into the consortium’s smart contracts only after the oracle inputs have two independent sources; an automatic hold based on a single unverified alert would create the false-positive and dispute costs the ledger is meant to avoid.", "key")
